import {fitMarkup,resizeTable,toggleFit} from './viewport.mjs';
import {captureVisuals,animateResult} from './feedback.mjs';
import {GameSound,soundEvents} from './sound.mjs';
import {Engine} from './engine.mjs';
import {table} from './table.mjs';
import {unsupported} from './coverage.mjs';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cards=[],decks=[],db={},verification={evidence:{}},page='setup',catalogPage=0,chosen=[0,1],cardsReady=false,cardsLoading=null;
let filters={q:'',type:'',color:'',set:''};
let engine,selected=[],attackFrom=null;
const sound=new GameSound();
document.addEventListener('pointerdown',()=>sound.unlock(),{capture:true,passive:true});
document.addEventListener('keydown',()=>sound.unlock(),{capture:true});
const app=$('#app'),modal=$('#modal');
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3200)}
function dialog(title,html){modal.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button data-act="close" aria-label="关闭">✕</button></div><div class="dialog-body">${html}</div>`;if(!modal.open)modal.showModal()}
function previewCard(uid){const pane=$('#hover-preview'),c=engine?.s?.cards?.[uid];if(!pane||!c)return;const d=engine.def(c),name=engine.name(c),stats=[d.type==='领袖'?`生命 ${d.life}`:`费用 ${d.cost}`,d.power?`力量 ${engine.power(c)}`:'',d.counter?`反击 +${d.counter}`:''].filter(Boolean);pane.innerHTML=`<div class="preview-card"><img src="${esc(d.thumbnail||d.image)}" alt="${esc(name)}"><div><small>${esc(d.id)} · ${esc(d.type)} · ${esc((d.colors||[]).join(' / '))}</small><h3>${esc(name)}</h3><div class="chips">${stats.map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div>${d.features?`<p class="preview-features">${esc(d.features)}</p>`:''}<p class="preview-effect">${esc(d.effect||'无额外效果。')}</p>${d.trigger?`<p class="preview-trigger">【触发】${esc(d.trigger)}</p>`:''}<small class="preview-hint">点击卡牌可查看完整中文效果并进行操作</small></div></div>`}
function header(){return `<header><div class="brand"><span class="brand-mark">⚓</span><div><strong>航海王 · 练习桌</strong><small>ONE PIECE CARD GAME</small></div></div><nav aria-label="主导航">${[['setup','练习'],['catalog','卡库'],['help','说明']].map(([p,n])=>`<button data-page="${p}" class="${page===p?'selected':''}">${n}</button>`).join('')}</nav><details class="sound-settings"><summary aria-label="音效设置">音效</summary><div class="sound-panel"><button data-soundmute aria-pressed="${sound.muted}">${sound.muted?'开启音效':'静音'}</button><label>音量 <output id="sound-level">${Math.round(sound.volume*100)}%</output><input type="range" data-soundvolume aria-label="音效音量" min="0" max="100" value="${Math.round(sound.volume*100)}"></label></div></details></header>`}
function cardButton(c){return `<button class="catalog-card" data-card="${c.id}" aria-label="查看 ${esc(c.name||c.nameEn)}"><img src="${c.thumbnail||c.image}" loading="lazy" alt="${esc(c.name||c.nameEn)}"><strong>${esc(c.name||c.nameEn)}</strong><small>${c.id} · ${c.type}</small></button>`}
function leader(deck){return Object.keys(deck?.cards||{}).map(id=>db[id]).find(c=>c?.type==='领袖')}
function deckCount(d){return Object.entries(d.cards).reduce((n,[id,v])=>n+(db[id]?.type==='领袖'?0:v),0)}
function render(){app.innerHTML=header()+`<main class="shell">${page==='table'&&engine?.s?fitMarkup(table(engine,engine.s.prompt?.owner??engine.s.active,selected,attackFrom)):page==='setup'?setup():page==='catalog'?catalog():help()}</main>`;resizeTable()}
function setup(){return `<div class="section-title"><div><div class="eyebrow">SOLO PRACTICE</div><h1>一张桌，两边都由你掌舵。</h1><p>选好双方卡组，开始一场自己的练习。</p></div><button data-act="import">导入卡组</button></div><div class="setup-grid">${[0,1].map(i=>{let d=decks[chosen[i]],c=leader(d);return `<section class="deck-panel ${i?'b':'a'}"><label for="deck${i}">${i?'P2 · 上方':'P1 · 下方'}</label><select id="deck${i}" data-deck="${i}">${decks.map((d,n)=>`<option value="${n}" ${n===chosen[i]?'selected':''}>${esc(d.name)}</option>`).join('')}</select>${c?`<div class="leader-preview"><img src="${c.thumbnail||c.image}" alt="${esc(c.name||c.nameEn)}"><div><small>${c.id} · 领袖</small><h2>${esc(c.name||c.nameEn)}</h2><div class="chips"><span class="chip">${c.colors.join(' / ')}</span><span class="chip">生命 ${c.life}</span><span class="chip">${deckCount(d)} 张主卡</span></div><div class="actions" style="margin-top:18px"><button data-card="${c.id}">中文效果</button><button data-viewdeck="${chosen[i]}">查看卡组</button></div></div></div>`:'<p>选择含领袖的卡组</p>'}</section>`}).join('')}</div><div class="setup-foot">${engine?.s?'<button data-resume>继续上次练习</button>':''}<div class="row"><label for="first">先攻</label><select id="first"><option value="0">P1</option><option value="1">P2</option><option value="random">随机决定</option></select></div><button class="primary" data-act="start">开始练习</button></div><div class="statsline"><span><strong>${cards.length.toLocaleString()}</strong>张卡牌</span><span><strong>${new Set(cards.map(c=>c.set)).size}</strong>个系列</span><span><strong>${decks.length}</strong>套卡组</span></div><p class="notice">原卡图 · 点击查看中文效果 · P1 固定在下 · P2 固定在上</p>`}
function filtered(){let q=filters.q.toLowerCase();return cards.filter(c=>(!q||[c.id,c.name,c.nameEn,c.features,c.effect].join(' ').toLowerCase().includes(q))&&(!filters.type||c.type===filters.type)&&(!filters.color||c.colors.includes(filters.color))&&(!filters.set||c.set===filters.set))}
function catalog(){let list=filtered(),max=Math.max(1,Math.ceil(list.length/48));catalogPage=Math.min(catalogPage,max-1);return `<div class="section-title"><div><div class="eyebrow">CARD LIBRARY</div><h1>全卡库</h1><p>按卡号、名称或效果搜索，点击卡牌查看中文说明。</p></div><button data-act="import">组建卡组</button></div><div class="filters"><input id="query" type="search" placeholder="搜索卡号、名称、效果…" value="${esc(filters.q)}" aria-label="搜索卡牌">${[['type','全部类型',['领袖','角色','事件','舞台']],['color','全部颜色',['红','绿','蓝','紫','黑','黄']],['set','全部系列',[...new Set(cards.map(c=>c.set))].sort()]].map(([k,n,vs])=>`<select data-filter="${k}" aria-label="${n}"><option value="">${n}</option>${vs.map(v=>`<option ${filters[k]===v?'selected':''}>${v}</option>`).join('')}</select>`).join('')}</div><p class="muted">找到 ${list.length} 张</p><div class="card-grid">${list.slice(catalogPage*48,(catalogPage+1)*48).map(cardButton).join('')}</div>${!list.length?'<p class="empty">没有找到，试试其他关键词。</p>':''}<div class="pagination"><button data-paging="-1" ${catalogPage===0?'disabled':''}>上一页</button><span>${catalogPage+1} / ${max}</span><button data-paging="1" ${catalogPage>=max-1?'disabled':''}>下一页</button></div>`}
async function ensureCards(){if(cardsReady)return;cardsLoading??=fetch('./data/cards.json?v=20260914i').then(async r=>{if(!r.ok)r=await fetch('./data/base.json?v=20260914i');if(!r.ok)throw Error('完整卡牌资料下载失败');return r.json()}).then(full=>{cards=full;db=Object.fromEntries(cards.map(c=>[c.id,c]));engine.db=db;cardsReady=true});await cardsLoading}
async function showCard(id){if(!cardsReady){dialog('正在加载卡牌详情','<p class="loading">正在读取完整卡牌资料…</p>');try{await ensureCards()}catch(e){modal.close();toast(e.message);return}}let c=db[id];if(!c)return;const tested=!!verification.evidence?.[id];dialog('卡牌详情',`<div class="detail"><img src="${c.image}" alt="${esc(c.name||c.nameEn)}"><div><small>${c.id} · ${c.type} · ${c.colors.join(' / ')}</small><h2>${esc(c.name||c.nameEn)}</h2><div class="chips"><span class="chip">${c.type==='领袖'?'生命 '+c.life:'费用 '+c.cost}</span>${c.power?`<span class="chip">力量 ${c.power}</span>`:''}${c.counter?`<span class="chip">反击 +${c.counter}</span>`:''}</div><p class="muted">${esc(c.features||'')}</p><p class="effect">${esc(c.effect||((c.name)?'无额外效果。':'正在核对中文效果。'))}</p>${c.trigger?`<p class="trigger">【触发】${esc(c.trigger)}</p>`:''}<p class="notice">${tested?'已纳入自动化规则测试；仍会继续逐条核验。':'尚未纳入自动化规则测试；不能据此视为已完全验证。'}</p><small>${esc(c.zhSource||'本地原版卡牌数据')}</small></div></div>`)}
function help(){return `<div class="section-title"><div class="eyebrow">PRACTICE GUIDE</div></div><article class="help"><h1>自己的对战练习。</h1><p>选择双方卡组后开始。P1 固定在下方，P2 固定在上方。手牌和操作提示会跟随当前需要操作的一方，牌桌位置保持不动。</p><p>点卡可查看中文效果。卡库支持搜索全部卡牌，预设卡组来自你提供的单机版本。</p><p>卡组文本格式：每行填写数量和卡号，例如 <code>1xST01-001</code>。主卡组为 50 张，另外选择 1 张领袖。</p><p>中文卡牌说明来源：<a href="https://www.onepiece-cardgame.cn/cardlist" target="_blank" rel="noopener">航海王卡牌对战中文官网</a>。原卡图来自本地游戏素材。</p></article>`}
function importDeck(){dialog('导入 / 组建卡组',`<form id="deckform" class="formstack"><label>卡组名称<input name="name" required maxlength="60" placeholder="我的路飞卡组"></label><label>卡组文本<textarea name="text" required placeholder="1xST01-001&#10;4xST01-002&#10;…"></textarea></label><p class="notice">支持原版 .deck 格式。每行：数量x卡号。需要 1 张领袖和 50 张主卡。</p><button class="primary" type="submit">保存卡组</button></form>`)}
document.addEventListener('click',async e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.page){if(b.dataset.page==='catalog'){b.disabled=true;b.textContent='正在载入卡库…';try{await ensureCards()}catch(err){toast(err.message);render();return}}page=b.dataset.page;render()}else if(b.dataset.card)showCard(b.dataset.card);else if(b.dataset.act==='close')modal.close();else if(b.dataset.act==='import')importDeck();else if(b.dataset.act==='start')startGame();else if(b.dataset.viewdeck){let d=decks[+b.dataset.viewdeck];dialog(d.name,`<div class="card-grid">${Object.keys(d.cards).filter(id=>db[id]).map(id=>`<div>${cardButton(db[id])}<p class="muted">× ${d.cards[id]}</p></div>`).join('')}</div>`)}else if(b.dataset.paging){catalogPage+=+b.dataset.paging;render();window.scrollTo({top:0,behavior:'smooth'})}});
document.addEventListener('change',e=>{if(e.target.dataset.deck){chosen[+e.target.dataset.deck]=+e.target.value;render()}if(e.target.dataset.filter){filters[e.target.dataset.filter]=e.target.value;catalogPage=0;render()}});
document.addEventListener('input',e=>{if(e.target.id==='query'){filters.q=e.target.value;catalogPage=0;let pos=e.target.selectionStart;render();$('#query').focus();$('#query').setSelectionRange(pos,pos)}});
document.addEventListener('submit',e=>{
 if(e.target.id!=='deckform')return;e.preventDefault();const f=new FormData(e.target),text=String(f.get('text')),entries={};
 try{for(const line of text.split(/\r?\n/).map(x=>x.trim()).filter(x=>x&&!x.startsWith('//'))){const m=line.match(/^(\d+)\s*x?\s*((?:OP|EB|ST|PRB|P)\d*-\d{3})(?:\s.*)?$/i);if(!m)throw Error('无法识别这一行：'+line);const id=m[2].toUpperCase();entries[id]=(entries[id]||0)+Number(m[1]);}
 const d={name:String(f.get('name')).trim(),cards:entries};const errors=engine.validateDeck(d);if(errors.length)throw Error(errors.join('；'));decks.push(d);const saved=JSON.parse(localStorage.getItem('opcg-decks')||'[]');saved.push(d);localStorage.setItem('opcg-decks',JSON.stringify(saved));chosen[0]=decks.length-1;modal.close();page='setup';render();toast('卡组已保存到当前设备');}catch(err){toast(err.message)}
});
let rulesReady=false,rulesLoading=null;
async function ensureRules(){if(rulesReady)return;rulesLoading??=fetch('./data/rules.json?v=20260914h').then(r=>{if(!r.ok)throw Error('规则数据下载失败');return r.json()}).then(r=>{engine.rules=r;rulesReady=true});await rulesLoading}
async function startGame(){try{const button=$('[data-act="start"]');if(button){button.disabled=true;button.textContent='正在准备对局…'}await Promise.all([ensureCards(),ensureRules()]);let first=$('#first').value;engine.start(chosen.map(i=>decks[i]),first==='random'?Math.floor(Math.random()*2):+first);page='table';selected=[];attackFrom=null;render();persist();sound.play(['start']);}catch(e){toast(e.message);render()}}
function persist(){try{if(engine.s)localStorage.setItem('opcg-game',JSON.stringify({s:engine.s,seed:engine.seed,serial:engine.serial}))}catch(e){toast('本机存储空间不足，当前对局暂未保存')}}
function gameCommand(c){try{const visual=captureVisuals(engine);const before=engine.s?structuredClone(engine.s):null;if(c.type==='undo')engine.undo();else engine.dispatch(c);const sounds=soundEvents(before,engine.s,c);selected=[];attackFrom=null;modal.close();persist();render();sound.play(sounds);animateResult(engine,visual,c);}catch(e){toast(e.message)}}
function boardClick(uid){const c=engine.s.cards[uid],p=engine.s.prompt;
 if(attackFrom){if(engine.canAttack(engine.s.cards[attackFrom],c)){gameCommand({type:'attack',uid:attackFrom,target:uid});return}toast(engine.attackReason(engine.s.cards[attackFrom],c));return}
 if(p?.candidates?.includes(uid)){if(!selected.includes(uid)&&!engine.targetAllowed(p,uid,selected)){toast('这张卡与已选卡同名，或不符合当前效果条件');return}selected=selected.includes(uid)?selected.filter(x=>x!==uid):selected.length<p.max?[...selected,uid]:p.max===1?[uid]:selected;render();return}
 const d=engine.def(c),owner=engine.s.active;let buttons='';
 if(!p&&c.owner===owner){if(c.zone==='hand'){const playCost=engine.playCost(c),reason=d.type==='事件'?engine.activationReason(c,engine.actions(c).findIndex(a=>a.proc.ActivateMain)):engine.readyDon(owner).length<playCost?`需要 ${playCost} 张可用 DON!!，当前只有 ${engine.readyDon(owner).length} 张`:'';buttons+=`<button class="primary" data-playuid="${uid}" ${reason?'disabled':''}>使用卡牌 · ${playCost} DON!!</button>${reason?`<p class="action-reason">${esc(reason)}</p>`:''}`;}if(['leader','field'].includes(c.zone)){buttons+=`<button data-attachuid="${uid}" ${!engine.readyDon(owner).length?'disabled':''}>附加 1 DON!!</button>`;if(engine.board(1-owner).some(t=>engine.canAttack(c,t)))buttons+=`<button data-attackuid="${uid}">选择攻击目标</button>`;else buttons+=`<p class="action-reason">无法攻击：${esc(engine.attackReason(c,engine.list(1-owner,'leader')[0]))}</p>`;if(!engine.readyDon(owner).length)buttons+='<p class="action-reason">无法附加：当前没有可用 DON!!。</p>';}if(['leader','field','stage'].includes(c.zone))engine.actions(c).forEach((a,i)=>{if(a.proc.ActivateMain){const reason=engine.activationReason(c,i);buttons+=`<button data-activateuid="${uid}" data-index="${i}" ${reason?'disabled':''}>发动效果 ${i+1}${a.proc.OncePerTurn?' · 每回合一次':''}</button>${reason?`<p class="action-reason">${esc(reason)}</p>`:''}`}});}
 if(p?.type==='counter'&&c.owner===p.owner&&c.zone==='hand'&&(engine.counter(c)>0||engine.actions(c).some(a=>a.proc.Counter)))buttons+=`<button class="primary" data-counteruid="${uid}">使用反击${engine.counter(c)?' +'+engine.counter(c):''}</button>`;
 if(p&&!p.candidates?.includes(uid))buttons+='<p class="action-reason">请先完成当前操作提示；亮框卡牌才是当前可选目标。</p>';else if(!p&&c.owner!==owner)buttons+=`<p class="action-reason">当前由 ${engine.label(owner)} 操作，这张卡属于另一方。</p>`;showCard(c.id);modal.querySelector('.detail').insertAdjacentHTML('beforeend',`<div class="card-command actions">${buttons}</div>`);
}
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;
 if(b.dataset.board)boardClick(b.dataset.board);
 else if(b.hasAttribute('data-answer'))gameCommand({type:'choose',value:b.dataset.answer});
 else if(b.hasAttribute('data-confirmtargets'))gameCommand({type:'choose',uids:selected});
 else if(b.dataset.gamecommand)gameCommand({type:b.dataset.gamecommand});
 else if(b.dataset.playuid)gameCommand({type:'play',uid:b.dataset.playuid});
 else if(b.dataset.attachuid)gameCommand({type:'attach',uid:b.dataset.attachuid});
 else if(b.dataset.activateuid)gameCommand({type:'activate',uid:b.dataset.activateuid,index:+b.dataset.index});
 else if(b.dataset.counteruid)gameCommand({type:'choose',uid:b.dataset.counteruid});
 else if(b.dataset.attackuid){attackFrom=b.dataset.attackuid;modal.close();render()}
 else if(b.hasAttribute('data-cancelattack')){attackFrom=null;render()}
 else if(b.dataset.detailuid)showCard(engine.s.cards[b.dataset.detailuid].id);
 else if(b.hasAttribute('data-log'))dialog('对局记录',engine.s.log.slice().reverse().map(x=>`<p><small>回合 ${x.turn}</small> ${esc(x.text)}</p>`).join(''));
 else if(b.dataset.zone){const [o,z]=b.dataset.zone.split(':');dialog(`${engine.label(+o)} · 弃牌区`,`<div class="card-grid">${engine.list(+o,z).map(c=>cardButton(db[c.id])).join('')}</div>`)}
 else if(b.hasAttribute('data-resume')){b.disabled=true;b.textContent='正在准备对局…';Promise.all([ensureCards(),ensureRules()]).then(()=>{page='table';render()}).catch(e=>{toast(e.message);render()})}
});
document.addEventListener('pointerover',e=>{const card=e.target.closest('[data-board]');if(card)previewCard(card.dataset.board)});
document.addEventListener('focusin',e=>{const card=e.target.closest('[data-board]');if(card)previewCard(card.dataset.board)});
async function init(){try{const [bootstrap,deckData,verificationData]=await Promise.all([fetch('./data/bootstrap.json?v=20260914i').then(r=>r.json()),fetch('./data/decks.json?v=20260914i').then(r=>r.json()),fetch('./data/verification.json?v=20260916e').then(r=>r.ok?r.json():{evidence:{}})]);cards=bootstrap;db=Object.fromEntries(cards.map(c=>[c.id,c]));decks=deckData.filter(d=>leader(d));verification=verificationData;engine=new Engine(cards,{});try{decks.push(...JSON.parse(localStorage.getItem('opcg-decks')||'[]'));const saved=JSON.parse(localStorage.getItem('opcg-game')||'null');if(saved?.s?.version===1||saved?.s?.version===2){engine.s=saved.s;engine.seed=saved.seed;engine.serial=saved.serial;engine.s.eventBatch??=0;engine.assertState();}}catch(e){console.warn('存档不可用',e);engine.s=null;}let a=decks.findIndex(d=>d.name.startsWith('ST01')),b=decks.findIndex(d=>d.name.startsWith('ST02'));chosen=[Math.max(a,0),Math.max(b,1)];render()}catch(e){app.innerHTML='<p class="loading">卡牌加载失败，请刷新重试。</p>';console.error(e)}}init();

document.addEventListener('click',e=>{const b=e.target.closest('[data-soundmute]');if(!b)return;sound.setMuted(!sound.muted);b.textContent=sound.muted?'开启音效':'静音';b.setAttribute('aria-pressed',String(sound.muted));if(!sound.muted){sound.unlock();sound.play(['don']);}});
document.addEventListener('input',e=>{if(!e.target.matches('[data-soundvolume]'))return;sound.setVolume(Number(e.target.value)/100);document.querySelector('#sound-level').textContent=e.target.value+'%';});

document.addEventListener('click',e=>{if(e.target.closest('[data-fit]')){toggleFit();render();window.scrollTo(0,0);}});
